import base64
import binascii
import re

with open('/home/ctfplayer/b64hex_candidates.txt') as f:
    lines = [line.strip() for line in f if line.strip()]

def try_print(s):
    try:
        txt = s.decode(errors='replace')
        print('Decoded text:', txt)
    except Exception:
        print('Raw bytes:', s)

for line in lines:
    print(f'Candidate: {line}')
    if line.startswith('x'):
        # Remove the starting 'x', and any '\x', join hex digits
        hex_str = line.lstrip('x')
        hex_str = re.sub(r'\\x', '', hex_str)  # remove \x
        hex_str = re.sub(r'[^0-9a-fA-F]', '', hex_str)  # remove non-hex
        try:
            data = binascii.unhexlify(hex_str)
            print('Unhexlify OK.')
            try_print(data)
            try:
                b64decoded = base64.b64decode(data)
                print('Base64-decode after hexdecode:')
                try_print(b64decoded)
            except Exception as e:
                print('Base64 decode after hexdecode failed:', e)
        except Exception as e:
            print('Unhexlify failed:', e)
    else:
        try:
            b64decoded = base64.b64decode(line)
            print('Base64-decode as is:')
            try_print(b64decoded)
        except Exception as e:
            print('Base64 direct decode failed:', e)
    print('-----')

import base64, re

strings_head = open('/home/ctfplayer/constela_strings_head.txt').readlines()
outputs = []

# 1. Extract long hex starting with \x42
hex_lines = []
for line in strings_head:
    if re.match(r'(\\x[0-9a-fA-F]{2}){8,}', line):
        hex_lines.append(line.strip())

# If present, convert \xHH... to hex, then try hex->ascii->base64-decode
for hexline in hex_lines:
    hexstr = hexline.replace('\\x','')
    try:
        bdata = bytes.fromhex(hexstr)
        outputs.append('Hex decode: ' + repr(bdata[:64]) + ('...' if len(bdata)>64 else ''))
        # Try base64
        try:
            b64d = base64.b64decode(bdata)
            with open('/home/ctfplayer/decoded_possiblefile', 'wb') as f:
                f.write(b64d)
            outputs.append('Base64 of hex: wrote /home/ctfplayer/decoded_possiblefile, first bytes: ' + str(b64d[:16]))
        except Exception as e:
            outputs.append('Could not base64 decode hex-ascii: ' + str(e))
    except Exception as e:
        outputs.append('Hex decode failed: ' + str(e))

# 2. Decode all base64 candidates
b64_candidates = []
for line in strings_head:
    if re.match(r'^[A-Za-z0-9+/=]{20,}$', line.strip()):
        b64_candidates.append(line.strip())
# Add those already extracted by shell above, in case
b64_candidates = list(set(b64_candidates + [
    'JEdQR0dBLCw0Mi4wLE4sMjcuMCxXLDcs',
    'MDAsLDEwMDE2LjAsZnQsLCwsKjQ3'
]))

for idx, b64line in enumerate(b64_candidates):
    try:
        b64d = base64.b64decode(b64line)
        preview = b64d[:32]
        outputs.append(f'Base64 #{idx}: {b64line} => {preview}')
        # If looks like image or file, save
        if b64d.startswith(b'\x89PNG') or b64d.startswith(b'JFIF') or b64d.startswith(b'GIF'):
            with open('/home/ctfplayer/base64_candidate_%d.img' % idx, 'wb') as f:
                f.write(b64d)
            outputs.append(f'Saved decoded image from base64 #{idx} to file /home/ctfplayer/base64_candidate_%d.img' % idx)
    except Exception as e:
        outputs.append(f'Base64 decode failed for: {b64line} -- {e}')

# Write summary
with open('/home/ctfplayer/decoding_summary.txt', 'w') as f:
    for line in outputs:
        f.write(line + '\n')

import base64
import re
import binascii

hex_base_candidates = []
b64_candidates = []

with open('/home/ctfplayer/base64_candidates.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        # Extract hex-like string that starts with x42 (?\x42...)
        if line.startswith('x42') or (line.startswith('\\x42') and len(line) > 4):
            hex_base_candidates.append(line)
        # Gather base64-looking
        elif re.fullmatch(r'[A-Za-z0-9+/=]+', line):
            b64_candidates.append(line)

report = ""
outputs = []
image_outputs = []
flag_fnd = []

def saveit(data, fname):
    with open(fname, 'wb') as f:
        f.write(data)

# Attempt to process hex strings
for i, hstr in enumerate(hex_base_candidates):
    hstr_clean = hstr
    hstr_clean = hstr_clean.replace('x', '').replace('\\', '')  # Remove x and backslashes
    try:
        # Try hex decode
        b = binascii.unhexlify(hstr_clean)
        saveit(b, f'/home/ctfplayer/hex_decoded_{i}.bin')
        report += f'Hex candidate {i}: length={len(hstr)}, hex decoded OK. Saved to hex_decoded_{i}.bin\n'
        try:
            b2 = base64.b64decode(b, validate=True)
            saveit(b2, f'/home/ctfplayer/hex_base64_{i}.bin')
            if b2[:4] == b'\x89PNG':
                image_outputs.append(f'hex_base64_{i}.bin')
            elif b2[:3] == b'\xff\xd8\xff':
                image_outputs.append(f'hex_base64_{i}.bin')
            report += f'Hex candidate {i}: base64 decoded OK. Saved to hex_base64_{i}.bin\n'
            try:
                # search for flag
                flags = re.findall(b'flag\{.*?\}', b2)
                if flags:
                    flag_fnd.extend([f.decode("utf-8") for f in flags])
            except:
                pass
        except Exception as e:
            report += f'Hex candidate {i}: base64 decode failed: {e}\n'
    except Exception as e:
        report += f'Hex candidate {i}: Failed to hex decode: {e}\n'

# Attempt to process all base64 candidates
for i, b64 in enumerate(b64_candidates):
    try:
        b = base64.b64decode(b64, validate=True)
        saveit(b, f'/home/ctfplayer/base64_{i}.bin')
        if b[:4] == b'\x89PNG':
            image_outputs.append(f'base64_{i}.bin')
        elif b[:3] == b'\xff\xd8\xff':
            image_outputs.append(f'base64_{i}.bin')
        try:
            s = b.decode('utf-8')
            report += f'Base64 {i}: Decoded to UTF-8 string: {s[:60]}...\n'
            flagmatch = re.findall(r'flag\{.*?\}', s)
            if flagmatch:
                flag_fnd.extend(flagmatch)
        except:
            report += f'Base64 {i}: binary output\n'
    except Exception as e:
        report += f'Base64 {i}: decode failed: {e}\n'

if image_outputs:
    report += f'Identified possible images: {image_outputs}\n'
if flag_fnd:
    report += f'Flags found: {flag_fnd}\n'
with open('/home/ctfplayer/constela_decode_report.txt', 'w') as f:
    f.write(report)
